import{_ as t,o as i,c as o,a2 as a}from"./chunks/framework.OWFDNrRT.js";const g=JSON.parse('{"title":"DINOForge v0.11.0 Release Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap/v0.11.md","filePath":"roadmap/v0.11.md","lastUpdated":1774507673000}'),r={name:"roadmap/v0.11.md"};function s(l,e,n,d,c,u){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="dinoforge-v0-11-0-release-roadmap" tabindex="-1">DINOForge v0.11.0 Release Roadmap <a class="header-anchor" href="#dinoforge-v0-11-0-release-roadmap" aria-label="Permalink to &quot;DINOForge v0.11.0 Release Roadmap&quot;">​</a></h1><blockquote><p><strong>Release Date</strong>: 2026-03-20 <strong>Previous</strong>: v0.10.0 (asset pipeline completion) <strong>Next</strong>: v0.12.0 (F9/F10 hotkey + native menu fixes)</p></blockquote><hr><h2 id="v0-11-0-—-what-s-included" tabindex="-1">v0.11.0 — What&#39;s Included <a class="header-anchor" href="#v0-11-0-—-what-s-included" aria-label="Permalink to &quot;v0.11.0 — What&#39;s Included&quot;">​</a></h2><h3 id="runtime-bridge-improvements" tabindex="-1">Runtime &amp; Bridge Improvements <a class="header-anchor" href="#runtime-bridge-improvements" aria-label="Permalink to &quot;Runtime &amp; Bridge Improvements&quot;">​</a></h3><ul><li><strong>BepInEx plugin stabilization</strong> — plugin loads without exception; HideAndDontSave root partially persists (RT-002 ⚠️ PARTIAL)</li><li><strong>Asset Swap Phase 2 timing</strong> — disk patches happen in <code>OnCreate</code> (immediate); live entity swaps on first <code>OnUpdate</code> with valid entity count instead of 600-frame delay</li><li><strong>CLI tools JSON output</strong> — all 11 commands support <code>--format json</code>; ANSI markup suppressed in JSON mode; <code>ui-expect</code> supports exit-code assertions</li><li><strong>Asset visual alignment</strong> — warfare-starwars pack updated with 14 unit + 9 building <code>visual_asset</code> corrections</li></ul><h3 id="desktop-companion-v0-11-0-complete" tabindex="-1">Desktop Companion (v0.11.0 COMPLETE) <a class="header-anchor" href="#desktop-companion-v0-11-0-complete" aria-label="Permalink to &quot;Desktop Companion (v0.11.0 COMPLETE)&quot;">​</a></h3><ul><li><strong>Dashboard page</strong> — displays pack count, load status summary, health indicators</li><li><strong>Pack List page</strong> — enable/disable toggle per pack; service persistence across restarts; error badge states</li><li><strong>Settings page</strong> — game path + backup location edit/save; persistence via registry</li><li><strong>Debug panel</strong> — entity count query via Bridge; live game diagnostic display</li></ul><h3 id="sdk-asset-pipeline" tabindex="-1">SDK &amp; Asset Pipeline <a class="header-anchor" href="#sdk-asset-pipeline" aria-label="Permalink to &quot;SDK &amp; Asset Pipeline&quot;">​</a></h3><ul><li><strong>No breaking changes</strong> to ContentLoader, registries, or schemas</li><li><strong>Asset swap registry</strong> — concurrent test isolation (Guid prefixes) fixes flaky counts</li><li><strong>warfare-starwars bundles</strong> — all 25 units/buildings aligned; fallback mesh extraction for prefab-based bundles works</li></ul><h3 id="quality-assurance" tabindex="-1">Quality Assurance <a class="header-anchor" href="#quality-assurance" aria-label="Permalink to &quot;Quality Assurance&quot;">​</a></h3><ul><li><strong>New test matrix entries</strong> (v0.11.0): <ul><li>RT-001…RT-005: BepInEx plugin + F9/F10 (RT-003/004 ❌, RT-005 ❌)</li><li>AST-007…AST-010: Asset swap phases + visual alignment (all ✅)</li><li>CLI-001…CLI-007: CLI JSON + UI automation (CLI-001/002/003/004 ✅; CLI-005/006/007 🔄)</li><li>MCP-001…MCP-010: MCP server tools (9/10 ✅; MCP-011 🔄)</li><li>HOT-001…HOT-004: Hot reload (all ✅)</li><li>NATIVE-001…NATIVE-003: Native menu (all ❌)</li><li>COMP-001…COMP-008: Companion ViewModel unit tests (all ✅)</li><li>COMP-UI-001…COMP-UI-006: Companion FlaUI automation (all 🆕)</li></ul></li></ul><h3 id="migration-to-net-11-preview-2" tabindex="-1">Migration to .NET 11 (Preview 2) <a class="header-anchor" href="#migration-to-net-11-preview-2" aria-label="Permalink to &quot;Migration to .NET 11 (Preview 2)&quot;">​</a></h3><ul><li><p><strong>Target Framework Updates</strong>:</p><ul><li>Tools (<code>Cli</code>, <code>McpServer</code>, <code>PackCompiler</code>, <code>DumpTools</code>, <code>GameControlCli</code>) → <code>net11.0</code></li><li>Tests (Unit, Integration, UI Automation) → <code>net11.0</code></li><li>DesktopCompanion → <code>net11.0-windows10.0.26100.0</code></li><li>Installer GUI → <code>net11.0-windows</code></li><li>Runtime, SDK, BepInEx.Core.dll shim → <code>netstandard2.0</code> (unchanged)</li><li>VFXPrefabGenerator → <code>net472</code> (unchanged)</li></ul></li><li><p><strong>CI Workflows</strong>: All workflows now install .NET 8 + 9 + 10 + 11; pinned <code>global.json</code> to <code>11.0.100-preview.2.26159.112</code></p></li></ul><hr><h2 id="v0-11-0-known-regressions-being-fixed" tabindex="-1">v0.11.0 Known Regressions (Being Fixed) <a class="header-anchor" href="#v0-11-0-known-regressions-being-fixed" aria-label="Permalink to &quot;v0.11.0 Known Regressions (Being Fixed)&quot;">​</a></h2><h3 id="issue-1-f9-f10-key-input-broken-rt-003-rt-004" tabindex="-1">Issue 1: F9/F10 Key Input Broken (RT-003, RT-004) <a class="header-anchor" href="#issue-1-f9-f10-key-input-broken-rt-003-rt-004" aria-label="Permalink to &quot;Issue 1: F9/F10 Key Input Broken (RT-003, RT-004)&quot;">​</a></h3><p><strong>Symptom</strong>: F9 and F10 key presses do not toggle debug overlay or mod menu.</p><p><strong>Root Cause</strong>: Win32 global key watcher hook fires and posts messages, but <code>KeyInputSystem.OnInput</code> callback is never invoked. The message dispatch chain is broken or the system is not registered properly.</p><p><strong>Impact</strong>:</p><ul><li>Debug overlay (F9) cannot be opened</li><li>Mod menu overlay (F10) cannot be toggled</li><li>All overlay automation tests fail (OVL-001/002)</li><li>Native &quot;Mods&quot; button cannot function as F10 equivalent (NATIVE-002)</li></ul><p><strong>Fix Status</strong>: 🔄 IN_PROGRESS <strong>Target</strong>: v0.12.0 <strong>Investigation</strong>: Check <code>KeyInputSystem.OnEnable()</code> watcher registration; verify Win32 message loop integration in <code>RuntimeDriver.Update()</code>.</p><hr><h3 id="issue-2-runtimedriver-ondestroy-fires-early-rt-005-native-001-003" tabindex="-1">Issue 2: RuntimeDriver.OnDestroy Fires Early (RT-005, NATIVE-001/003) <a class="header-anchor" href="#issue-2-runtimedriver-ondestroy-fires-early-rt-005-native-001-003" aria-label="Permalink to &quot;Issue 2: RuntimeDriver.OnDestroy Fires Early (RT-005, NATIVE-001/003)&quot;">​</a></h3><p><strong>Symptom</strong>: Root GameObject with <code>HideAndDontSave</code> flag is destroyed at frame ~6 (approximately 100ms) instead of persisting ≥ 600 frames (~10s).</p><p><strong>Root Cause</strong>: Unknown. Suspected interactions:</p><ul><li>Scene unload lifecycle triggering premature cleanup</li><li>Conflict with DINO&#39;s two-boot cycle destroying the root</li><li><code>OnDestroy</code> being called unexpectedly from <code>RuntimeDriver</code> or BepInEx lifecycle</li></ul><p><strong>Impact</strong>:</p><ul><li><code>HideAndDontSave</code> persistence does not survive restart (RT-002 ⚠️ PARTIAL)</li><li><code>RuntimeDriver.Update()</code> loop terminates early, stopping KeyInputSystem polling</li><li>Native &quot;Mods&quot; button cannot persist in main menu (NATIVE-001/003)</li><li>F9/F10 fixes (Issue 1) also blocked until RuntimeDriver survives ≥ 600 frames</li></ul><p><strong>Fix Status</strong>: 🔄 IN_PROGRESS <strong>Target</strong>: v0.12.0 <strong>Investigation</strong>: Check <code>RuntimeDriver.OnDestroy()</code> stack trace; verify <code>HideAndDontSave</code> flag is set before first scene load; test persistence across explicit <code>SceneManager.LoadScene()</code> calls.</p><hr><h3 id="issue-3-ugui-overlay-alpha-visible-by-default-ovl-006" tabindex="-1">Issue 3: UGUI Overlay Alpha Visible by Default (OVL-006) <a class="header-anchor" href="#issue-3-ugui-overlay-alpha-visible-by-default-ovl-006" aria-label="Permalink to &quot;Issue 3: UGUI Overlay Alpha Visible by Default (OVL-006)&quot;">​</a></h3><p><strong>Symptom</strong>: Mod menu overlay is partially visible (alpha &gt; 0) before user presses F10.</p><p><strong>Root Cause</strong>: <code>HudStrip.AlphaBase</code> suppression logic not triggering until first F10 press.</p><p><strong>Impact</strong>: Visual clutter on screen until user explicitly opens overlay.</p><p><strong>Fix Status</strong>: ⚠️ PARTIAL <strong>Target</strong>: v0.12.0 (verify in live game) <strong>Investigation</strong>: Merged fix in v0.11.0; requires live game QA to confirm <code>AlphaBase</code> is 0 until F10 pressed.</p><hr><h2 id="v0-12-0-—-planned-work" tabindex="-1">v0.12.0 — Planned Work <a class="header-anchor" href="#v0-12-0-—-planned-work" aria-label="Permalink to &quot;v0.12.0 — Planned Work&quot;">​</a></h2><h3 id="tier-1-hotkey-native-menu-blocks-ovl-tests" tabindex="-1">Tier 1: Hotkey &amp; Native Menu (Blocks OVL tests) <a class="header-anchor" href="#tier-1-hotkey-native-menu-blocks-ovl-tests" aria-label="Permalink to &quot;Tier 1: Hotkey &amp; Native Menu (Blocks OVL tests)&quot;">​</a></h3><ol><li><p><strong>Fix RT-003/RT-004</strong> — Restore F9/F10 key input path</p><ul><li>Debug: Win32 watcher message dispatch</li><li>Fix: <code>KeyInputSystem.OnInput</code> invocation</li><li>Tests: RT-003, RT-004 ✅ PASS</li><li>Unlocks: OVL-001/002 (overlay toggle tests)</li></ul></li><li><p><strong>Fix RT-005</strong> — RuntimeDriver persistence ≥ 600 frames</p><ul><li>Debug: <code>OnDestroy</code> early firing root cause</li><li>Fix: <code>HideAndDontSave</code> persistence or alternative scene-load strategy</li><li>Tests: RT-005 ✅ PASS</li><li>Unlocks: NATIVE-001/003, Menu injection tests</li></ul></li><li><p><strong>Native &quot;Mods&quot; Button Injection</strong> — Menu injection + survival</p><ul><li>Create native button between Options and Credits</li><li>Wired to F10 (overlay toggle)</li><li>Tests: NATIVE-001/002/003 ✅ PASS</li><li>Depends on: RT-003/004/005 fixes</li></ul></li></ol><h3 id="tier-2-overlay-automation-e2e-depends-on-tier-1" tabindex="-1">Tier 2: Overlay Automation &amp; E2E (Depends on Tier 1) <a class="header-anchor" href="#tier-2-overlay-automation-e2e-depends-on-tier-1" aria-label="Permalink to &quot;Tier 2: Overlay Automation &amp; E2E (Depends on Tier 1)&quot;">​</a></h3><ol start="4"><li><p><strong>In-Game Overlay UI Automation</strong> — OVL-001…008</p><ul><li>Toggle tests (OVL-001/002)</li><li>Pack list display (OVL-003)</li><li>Pack toggle (OVL-004)</li><li>Debug panel (OVL-005/006)</li><li>Settings persistence (OVL-008)</li><li>Tests: All OVL-* ✅ PASS</li><li>Depends on: RT-003/004 fixes</li></ul></li><li><p><strong>Game Launch E2E Suite</strong> — GL-001…008</p><ul><li>Smoke test (GL-001)</li><li>Pack load (GL-002)</li><li>Asset swap phase 1/2 (GL-003/004)</li><li>Stat persistence (GL-005)</li><li>Overlay in-game (GL-006)</li><li>Hot reload (GL-007)</li><li>Economy pack (GL-008)</li><li>Depends on: RT-003/004/005, NATIVE injection</li></ul></li></ol><h3 id="tier-3-cli-mcp-completion" tabindex="-1">Tier 3: CLI &amp; MCP Completion <a class="header-anchor" href="#tier-3-cli-mcp-completion" aria-label="Permalink to &quot;Tier 3: CLI &amp; MCP Completion&quot;">​</a></h3><ol start="6"><li><p><strong>CLI UI Automation Commands</strong> — CLI-005/006/007</p><ul><li><code>ui click</code> targeting by AutomationId</li><li><code>ui wait</code> polling + timeout</li><li><code>ui expect</code> exit code assertions</li><li>Tests: CLI-005/006/007 ✅ PASS</li></ul></li><li><p><strong>MCP Server Tool Completion</strong> — MCP-011</p><ul><li><code>game_ui_automation</code> in-game driver</li><li>Tests: MCP-011 ✅ PASS</li></ul></li></ol><h3 id="tier-4-coverage-gap-closure" tabindex="-1">Tier 4: Coverage Gap Closure <a class="header-anchor" href="#tier-4-coverage-gap-closure" aria-label="Permalink to &quot;Tier 4: Coverage Gap Closure&quot;">​</a></h3><ol start="8"><li><p><strong>Fuzz Testing Targets</strong> — FUZZ-004/005</p><ul><li>Asset catalog fuzzing</li><li>Schema validation fuzzing</li></ul></li><li><p><strong>Performance Benchmarks</strong> — PERF-003/004</p><ul><li>Bridge latency P99 &lt; 50ms</li><li>Asset swap phase 1 &lt; 5 frames</li></ul></li></ol><hr><h2 id="qa-coverage-path-v0-11-0-→-v0-12-0" tabindex="-1">QA Coverage Path (v0.11.0 → v0.12.0) <a class="header-anchor" href="#qa-coverage-path-v0-11-0-→-v0-12-0" aria-label="Permalink to &quot;QA Coverage Path (v0.11.0 → v0.12.0)&quot;">​</a></h2><h3 id="current-state-v0-11-0" tabindex="-1">Current State (v0.11.0) <a class="header-anchor" href="#current-state-v0-11-0" aria-label="Permalink to &quot;Current State (v0.11.0)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Layer</th><th>Pass Rate</th><th>Blocker(s)</th><th>Status</th></tr></thead><tbody><tr><td>SDK (unit)</td><td>95%</td><td>None</td><td>✅ STABLE</td></tr><tr><td>Bridge Protocol</td><td>85%</td><td>None</td><td>✅ STABLE</td></tr><tr><td>Asset Swap</td><td>100%</td><td>None</td><td>✅ STABLE</td></tr><tr><td>Runtime / BepInEx</td><td>17%</td><td>RT-003/004/005</td><td>❌ BLOCKED</td></tr><tr><td>CLI Tools</td><td>57%</td><td>CLI-005/006/007</td><td>🔄 IN_PROGRESS</td></tr><tr><td>MCP Server</td><td>91%</td><td>MCP-011</td><td>🔄 IN_PROGRESS</td></tr><tr><td>Hot Reload</td><td>100%</td><td>None</td><td>✅ STABLE</td></tr><tr><td>Native Menu</td><td>0%</td><td>RT-005</td><td>❌ BLOCKED</td></tr><tr><td>Overlay UI</td><td>0%</td><td>RT-003/004</td><td>❌ BLOCKED</td></tr><tr><td>Desktop Companion</td><td>100%</td><td>None</td><td>✅ STABLE</td></tr><tr><td>E2E / Game Launch</td><td>0%</td><td>RT-003/004/005</td><td>❌ BLOCKED</td></tr></tbody></table><h3 id="post-v0-12-0-target-80" tabindex="-1">Post-v0.12.0 Target (80%+) <a class="header-anchor" href="#post-v0-12-0-target-80" aria-label="Permalink to &quot;Post-v0.12.0 Target (80%+)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Layer</th><th>Target</th><th>Notes</th></tr></thead><tbody><tr><td>SDK (unit)</td><td>95%</td><td>No regression expected</td></tr><tr><td>Bridge Protocol</td><td>90%</td><td>Latency P99 tests (PERF-003)</td></tr><tr><td>Asset Swap</td><td>95%</td><td>Phase 1/2 timing tests (PERF-004)</td></tr><tr><td>Runtime / BepInEx</td><td>100%</td><td>All RT-* tests ✅ PASS</td></tr><tr><td>CLI Tools</td><td>100%</td><td>CLI-005/006/007 complete</td></tr><tr><td>MCP Server</td><td>100%</td><td>MCP-011 complete</td></tr><tr><td>Hot Reload</td><td>100%</td><td>No regression expected</td></tr><tr><td>Native Menu</td><td>100%</td><td>NATIVE-001/002/003 ✅ PASS</td></tr><tr><td>Overlay UI</td><td>100%</td><td>OVL-001…008 ✅ PASS</td></tr><tr><td>Desktop Companion</td><td>100%</td><td>No regression expected</td></tr><tr><td>E2E / Game Launch</td><td>95%</td><td>GL-001…008 ✅ PASS (most)</td></tr></tbody></table><hr><h2 id="release-notes-highlights-v0-11-0" tabindex="-1">Release Notes Highlights (v0.11.0) <a class="header-anchor" href="#release-notes-highlights-v0-11-0" aria-label="Permalink to &quot;Release Notes Highlights (v0.11.0)&quot;">​</a></h2><h3 id="✅-delivered" tabindex="-1">✅ Delivered <a class="header-anchor" href="#✅-delivered" aria-label="Permalink to &quot;✅ Delivered&quot;">​</a></h3><ul><li>.NET 11 migration complete</li><li>Desktop Companion UI fully functional (Dashboard, Pack List, Settings, Debug)</li><li>CLI JSON output for all 13 commands</li><li>Asset swap timing fixes (immediate disk patch, responsive entity swap)</li><li>warfare-starwars visual asset alignment (14 units + 9 buildings)</li><li>Comprehensive QA matrix with 80+ test cases</li></ul><h3 id="⚠️-known-issues" tabindex="-1">⚠️ Known Issues <a class="header-anchor" href="#⚠️-known-issues" aria-label="Permalink to &quot;⚠️ Known Issues&quot;">​</a></h3><ul><li>F9/F10 key input not working (will fix in v0.12.0)</li><li>RuntimeDriver early destruction (will fix in v0.12.0)</li><li>Native &quot;Mods&quot; button not injected (depends on RuntimeDriver fix)</li></ul><h3 id="📊-metrics" tabindex="-1">📊 Metrics <a class="header-anchor" href="#📊-metrics" aria-label="Permalink to &quot;📊 Metrics&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Metric</th><th>v0.11.0</th></tr></thead><tbody><tr><td>Test Cases</td><td>80+</td></tr><tr><td>Test Pass Rate</td><td>~70% (30% blocked on RT-005)</td></tr><tr><td>Code Coverage (SDK)</td><td>~65%</td></tr><tr><td>Known Regressions</td><td>3 (all targeted for v0.12.0)</td></tr><tr><td>Documentation Pages</td><td>15+</td></tr></tbody></table><hr><h2 id="migration-guide-v0-10-0-→-v0-11-0" tabindex="-1">Migration Guide (v0.10.0 → v0.11.0) <a class="header-anchor" href="#migration-guide-v0-10-0-→-v0-11-0" aria-label="Permalink to &quot;Migration Guide (v0.10.0 → v0.11.0)&quot;">​</a></h2><h3 id="for-mod-authors" tabindex="-1">For Mod Authors <a class="header-anchor" href="#for-mod-authors" aria-label="Permalink to &quot;For Mod Authors&quot;">​</a></h3><ul><li>No breaking changes to pack.yaml or content schemas</li><li>Asset bundles work as before (Phase 2 timing improved)</li><li>Hot reload continues to work</li></ul><h3 id="for-net-sdk-consumers" tabindex="-1">For .NET SDK Consumers <a class="header-anchor" href="#for-net-sdk-consumers" aria-label="Permalink to &quot;For .NET SDK Consumers&quot;">​</a></h3><ul><li>Update TFM to <code>net11.0</code> (if targeting CLI tools/tests)</li><li>No API changes; recompile against new DLL versions</li><li><code>netstandard2.0</code> runtime plugin remains compatible with .NET 8+</li></ul><h3 id="for-contributors" tabindex="-1">For Contributors <a class="header-anchor" href="#for-contributors" aria-label="Permalink to &quot;For Contributors&quot;">​</a></h3><ul><li>Use <code>dotnet 11.0.100-preview.2.26159.112</code> (via global.json)</li><li>Run <code>dotnet test</code> against all tier-1 test projects (SDK, Bridge, CLI)</li><li>Do NOT test game launch until v0.12.0 (F9/F10 fixes)</li></ul><hr><h2 id="deployment-checklist-v0-11-0" tabindex="-1">Deployment Checklist (v0.11.0) <a class="header-anchor" href="#deployment-checklist-v0-11-0" aria-label="Permalink to &quot;Deployment Checklist (v0.11.0)&quot;">​</a></h2><ul><li>[ ] All SDK + Bridge tests passing on CI</li><li>[ ] All CLI tests passing (except CLI-005/006/007)</li><li>[ ] All MCP server tests passing (except MCP-011)</li><li>[ ] Hot reload tests all green</li><li>[ ] Desktop Companion unit + UI automation tests green</li><li>[ ] Asset swap tests 100% passing</li><li>[ ] No compiler warnings on <code>net11.0</code> TFM</li><li>[ ] CHANGELOG.md updated with v0.11.0 section</li><li>[ ] QA_MATRIX.md updated with new test cases</li><li>[ ] VERSION file = <code>0.11.0</code></li><li>[ ] GitHub release created with known issues listed</li><li>[ ] Docs site (VitePress) updated with v0.11.0 release notes</li></ul><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><strong>QA_MATRIX.md</strong> — Master test matrix with all test cases and status</li><li><strong>CHANGELOG.md</strong> — Complete change log (v0.11.0 section added)</li><li><strong>CLAUDE.md</strong> — Project governance and agent rules</li><li><strong>docs/roadmap/</strong> — All version roadmaps</li></ul>',74)])])}const h=t(r,[["render",s]]);export{g as __pageData,h as default};
